//! Table tests of the static type of `Exponentiate` and `MultiplyGroup`. sigmastate types both `GroupElement`
//! whatever their operands are (v6.0.6 `trees.scala:1028-1031`, `:1050-1053`: both mix in
//! `NotReadyValueGroupElement`, `values.scala:755-757`), and its parser builds them over operands of any type.
//!
//! The rows are sigma-state 6.0.7's at activated version 3 (the round's `measure/rows/s2.txt` with
//! `out/jvm-s2.txt`, and `rows/trees.txt` with `out/jvm-trees.txt`; generated by
//! `measure/tests/gen_rows_test.py`).
use crate::ergo_tree::{ErgoTree, ErgoTreeVersion};
use crate::mir::expr::Expr;
use crate::serialization::sigma_byte_reader::from_bytes;
use crate::serialization::sigma_byte_reader::SigmaByteRead;
use crate::serialization::SigmaSerializable;
use alloc::string::String;
use alloc::vec::Vec;

/// A row: its name in the round's row set, the expression's bytes, the tree version, then `REFUSED` where the
/// parser refuses the expression or the expression's static type as the type writer writes it at tree
/// version 3. The expression is a lambda `{(p: T) => node}` with `p` as the node's first operand (`op0`), its
/// second (`op1`) or both (`all`), so its type is `(T) => <the node's type>`: `70 01 <T> <the node's type> 00`
type TypeRow = (&'static str, &'static str, u8, &'static str);

/// The rows whose parse outcome or static type is not the table's
#[allow(clippy::unwrap_used)]
fn wrong_types(rows: &[TypeRow]) -> Vec<String> {
    let mut wrong = Vec::new();
    for (name, body, version, expected) in rows {
        let bytes = base16::decode(body.as_bytes()).unwrap();
        let got = match from_bytes(&bytes)
            .with_tree_version(ErgoTreeVersion::from(*version), Expr::sigma_parse)
        {
            Err(_) => "REFUSED".into(),
            Ok(expr) => base16::encode_lower(&expr.tpe().sigma_serialize_bytes().unwrap()),
        };
        if got != *expected {
            wrong.push(alloc::format!("{name}: expected {expected}, got {got}"));
        }
    }
    wrong
}

fn assert_types(rows: &[TypeRow]) {
    let wrong = wrong_types(rows);
    assert!(
        wrong.is_empty(),
        "{} of {}:\n{}",
        wrong.len(),
        rows.len(),
        wrong.join("\n")
    );
}

