#[test]
fn a_multiply_group_is_typed_a_group_element() {
    assert_eq!(MULTIPLY_GROUP_TYPE_ROWS.len(), 982);
    assert_types(MULTIPLY_GROUP_TYPE_ROWS);
}

/// A tree: its name, its bytes, and what sigmastate's `deserializeErgoTree` does with it at activated version
/// 3: `PARSED`, `UNPARSED` (a tree with the size flag whose root is refused by a validation rule) or
/// `REJECTED` (it throws). The roots: `true-prop` is `sigmaProp(true)`; `exp`, `mul` and `filter` are the
/// node alone (no proposition) and under other nodes; `prop.…` is a proposition holding the node, `untaken`
/// behind `true ||` (but `prop.untaken.size-filter.int` behind `true &&`, where the branch is taken: a
/// control). The review's roots: `root.….sp` is the node over a `SigmaProp`-typed left operand, which was
/// read as a proposition while the node took that operand's type and is no proposition (degraded with the
/// size flag, rejected without); `seg.…` holds the left operand as a segregated constant; `prop.…val-…`
/// holds the node in a `val`. Each root as tree version 0 without a size, and 0, 1 and 3 with one.
type TreeRow = (&'static str, &'static str, &'static str);

#[test]
#[allow(clippy::unwrap_used)]
fn a_tree_holding_a_group_operation_is_read_as_the_jvm_reads_it() {
    assert_eq!(TREE_ROWS.len(), 164);
    let mut wrong = Vec::new();
    for (name, tree, expected) in TREE_ROWS {
        let bytes = base16::decode(tree.as_bytes()).unwrap();
        let got = match from_bytes(&bytes).with_versions(
            ErgoTreeVersion::V3,
            ErgoTreeVersion::V3,
            ErgoTree::sigma_parse,
        ) {
            Err(_) => "REJECTED",
            Ok(ErgoTree::Unparsed { .. }) => "UNPARSED",
            Ok(ErgoTree::Parsed(_)) => "PARSED",
        };
        if got != *expected {
            wrong.push(alloc::format!("{name}: expected {expected}, got {got}"));
        }
    }
    assert!(
        wrong.is_empty(),
        "{} of {}:\n{}",
        wrong.len(),
        TREE_ROWS.len(),
        wrong.join("\n")
    );
}

